dangerouslySetInnerHTML.__html:
@keyframes page-enter {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: none; }
}
/* backwards, not both: a forwards fill holds the final keyframe, and a held
   transform computes to an identity matrix rather than none. That matrix is
   still a containing block, so every position: fixed descendant would resolve
   against this wrapper instead of the viewport. */
.page-enter { animation: page-enter 160ms cubic-bezier(0.16, 1, 0.3, 1) backwards; }
@media (prefers-reduced-motion: reduce) {
  .page-enter { animation: none; }
}
